<?php require 'common.php';admin_required();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=db()->prepare('SELECT password_hash FROM users WHERE id=?');$s->execute([$_SESSION['admin_id']]);$hash=$s->fetchColumn();$old=(string)($_POST['old']??'');$new=(string)($_POST['new']??'');if(!password_verify($old,$hash))$msg='Senha atual incorreta.';elseif(strlen($new)<12||strlen($new)>200)$msg='A senha nova precisa de 12 a 200 caracteres.';else{db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$_SESSION['admin_id']]);session_regenerate_id(true);admin_log('change-password');$msg='Senha atualizada.';}}admin_top('Minha conta');?><?php if($msg):?><div class="alert"><?=h($msg)?></div><?php endif;?><div class="login"><h2>Alterar senha</h2><form method="post"><?=token_field()?><label>Senha atual<input type="password" name="old" required autocomplete="current-password"></label><label>Nova senha (mínimo 12 caracteres)<input type="password" name="new" required minlength="12" autocomplete="new-password"></label><button class="button red">ATUALIZAR</button></form></div><?php admin_bottom(); ?>
